import { DOCUMENT_KINDS, expect, expectStatus, test, uniqueName, type Document, type Vendor } from "../../fixtures";

test.describe("insurance expiry boundary", () => {
  test("a certificate that expires today can still be approved", { tag: "@LIF-07" }, async ({ apiAs, factory }) => {
    // Arrange: the server's "today" is the UTC date, and the test server doesn't pin its clock,
    // so the certificate states today's UTC date as its expiry.
    const today = new Date().toISOString().slice(0, 10);
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");
    const vendor = await factory.vendor({ name: uniqueName("Expires Today") });
    await factory.upload(vendor.id, "w9");
    await factory.upload(vendor.id, "contract");
    const certificate = await expectStatus<Document>(
      await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: "insurance_expires_today.txt",
            mimeType: "text/plain",
            buffer: Buffer.from(
              `Insurer: Harbor Mutual\nPolicy Number: LIF-07\nCoverage Amount: $2,000,000\nExpiry Date: ${today}\n`,
            ),
          },
        },
      }),
      201,
    );
    await expect
      .poll(
        async () => {
          const documents = await expectStatus<Document[]>(
            await member.get(`/api/vendors/${vendor.id}/documents`),
            200,
          );
          return documents.map((d) => d.status);
        },
        { message: "extraction finishes for all three documents", timeout: 30_000 },
      )
      .toEqual(DOCUMENT_KINDS.map(() => "extracted"));
    await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
    const extraction = await factory.extraction(certificate.id);
    expect(extraction.status).toBe("pending_review");

    // Act
    const response = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
      data: { decision: "approve" },
    });

    // Assert
    const decided = await expectStatus<{ status: string }>(response, 200);
    expect(decided.status).toBe("approved");
    expect((await factory.extraction(certificate.id, "reviewer")).status).toBe("approved");
  });
});
